<template>
  <div class="page-card">
    <h3>药库管理</h3>
    <el-form inline size="small" class="search-bar" @submit.native.prevent="search"><el-form-item label="药品检索"><el-input v-model.trim="query.keyword" placeholder="编码 名称 助记码" clearable @keyup.enter.native="search" /></el-form-item><el-form-item><el-button type="primary" :loading="loading" @click="search">查询</el-button><el-button @click="query.keyword='';search()">重置</el-button><el-button type="success" @click="edit()">新增药品</el-button></el-form-item></el-form>
    <el-alert title="停用药品保留历史记录。新建药品库存为0，需入库后才能发药。所有库存变动均记录流水。" type="info" :closable="false" />
    <el-table :data="rows" v-loading="loading" border size="small">
      <el-table-column prop="drugCode" label="编码" width="100" /><el-table-column prop="drugName" label="药品名称" min-width="120" /><el-table-column prop="drugFormat" label="规格" min-width="120" /><el-table-column prop="drugUnit" label="单位" width="65" /><el-table-column prop="manufacturer" label="厂家" min-width="130" /><el-table-column prop="mnemonicCode" label="助记码" width="100" />
      <el-table-column label="单价" width="90"><template slot-scope="{row}">¥{{ Number(row.drugPrice).toFixed(2) }}</template></el-table-column><el-table-column prop="stockQuantity" label="库存" width="75" /><el-table-column label="状态" width="75"><template slot-scope="{row}"><el-tag size="mini" :type="row.delmark===1?'success':'info'">{{ row.delmark===1?'在用':'停用' }}</el-tag></template></el-table-column>
      <el-table-column label="操作" width="200" fixed="right"><template slot-scope="{row}"><el-button type="text" :disabled="busy" @click="edit(row)">编辑</el-button><el-button type="text" :disabled="busy" @click="openStock(row)">库存操作</el-button><el-button type="text" :disabled="row.delmark!==1 || busy" @click="disable(row)">停用</el-button></template></el-table-column>
    </el-table>
    <el-pagination layout="total, prev, pager, next" :total="total" :page-size="query.size" :current-page.sync="query.page" @current-change="load" />
    <el-dialog :title="form.id ? '编辑药品' : '新增药品'" :visible.sync="visible" width="620px" :close-on-click-modal="false" :before-close="close">
      <el-form ref="form" :model="form" :rules="rules" label-width="100px" size="small" :disabled="busy">
        <el-form-item label="药品编码" prop="drugCode"><el-input v-model.trim="form.drugCode" maxlength="255" /></el-form-item><el-form-item label="药品名称" prop="drugName"><el-input v-model.trim="form.drugName" maxlength="255" /></el-form-item><el-form-item label="规格"><el-input v-model.trim="form.drugFormat" maxlength="255" /></el-form-item><el-form-item label="包装单位" prop="drugUnit"><el-input v-model.trim="form.drugUnit" maxlength="16" /></el-form-item><el-form-item label="生产厂家"><el-input v-model.trim="form.manufacturer" maxlength="255" /></el-form-item><el-form-item label="剂型"><el-input v-model.trim="form.drugDosage" maxlength="64" /></el-form-item><el-form-item label="药品类型"><el-input v-model.trim="form.drugType" maxlength="64" /></el-form-item><el-form-item label="单价" prop="drugPrice"><el-input-number v-model="form.drugPrice" :min="0" :max="999999.99" :precision="2" /></el-form-item><el-form-item label="助记码"><el-input v-model.trim="form.mnemonicCode" maxlength="255" /></el-form-item>
      </el-form><span slot="footer"><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></span>
    </el-dialog>
    <el-dialog title="库存操作" :visible.sync="stockVisible" width="530px" :close-on-click-modal="false" :before-close="close">
      <p v-if="selected">{{ selected.drugName }} · 当前库存 {{ selected.stockQuantity }} {{ selected.drugUnit }}</p>
      <el-form label-width="100px" size="small" :disabled="busy"><el-form-item label="操作类型"><el-select v-model="stockForm.type"><el-option v-for="t in ['入库','报损','盘点']" :key="t" :label="t" :value="t" /></el-select></el-form-item><el-form-item :label="stockForm.type==='盘点'?'实际总库存':'本次变动量'" required><el-input-number v-model="stockForm.quantity" :min="stockForm.type==='盘点'?0:1" :max="1000000" :precision="0" /></el-form-item><el-form-item label="操作原因" required><el-input v-model.trim="stockForm.reason" type="textarea" maxlength="255" show-word-limit /></el-form-item></el-form>
      <span slot="footer"><el-button :disabled="busy" @click="stockVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveStock">确认</el-button></span>
    </el-dialog>
  </div>
</template>
<script>
import {drugs,saveDrug,disableDrug,stock} from '@/api/pharmacy'
function blank(){return {id:null,drugCode:'',drugName:'',drugFormat:'',drugUnit:'',manufacturer:'',drugDosage:'',drugType:'',drugPrice:0,mnemonicCode:''}}
export default {name:'PharmacyDrugs',data(){return {query:{keyword:'',page:1,size:20},rows:[],total:0,loading:false,busy:false,visible:false,stockVisible:false,selected:null,form:blank(),stockForm:{type:'入库',quantity:1,reason:''},rules:{drugCode:[{required:true,message:'请输入药品编码',trigger:'blur'}],drugName:[{required:true,message:'请输入药品名称',trigger:'blur'}],drugUnit:[{required:true,message:'请输入包装单位',trigger:'blur'}],drugPrice:[{required:true,message:'请输入价格',trigger:'blur'}]}}},created(){this.load()},methods:{search(){this.query.page=1;this.load()},async load(){this.loading=true;try{const d=await drugs(this.query);this.rows=d.items;this.total=d.total}catch(e){/* 请求层提示 */}finally{this.loading=false}},edit(row){this.form=row?{...row}:blank();this.visible=true;this.$nextTick(()=>this.$refs.form.clearValidate())},close(done){if(!this.busy)done()},save(){this.$refs.form.validate(async valid=>{if(!valid||this.busy)return;this.busy=true;try{await saveDrug(this.form);this.$message.success('药品信息已保存');this.visible=false;await this.load()}catch(e){/* 保留表单 */}finally{this.busy=false}})},async disable(row){if(this.busy)return;try{await this.$confirm('确认停用 '+row.drugName+'？历史处方和交易将保留。','停用药品',{type:'warning'});this.busy=true;await disableDrug(row.id);this.$message.success('药品已停用');await this.load()}catch(e){/* 取消或请求层提示 */}finally{this.busy=false}},openStock(row){this.selected={...row};this.stockForm={type:'入库',quantity:1,reason:''};this.stockVisible=true},async saveStock(){if(this.busy)return;if(!this.stockForm.reason)return this.$message.warning('请填写操作原因');this.busy=true;try{await stock(this.selected.id,this.stockForm);this.$message.success('库存已更新');this.stockVisible=false;await this.load()}catch(e){/* 保留表单 */}finally{this.busy=false}}}}
</script>
<style scoped>h3{margin-top:0}.el-alert{margin-bottom:16px}.el-pagination{margin-top:16px}</style>
